-- The owner records a purpose with a reason. Replay-safe: recording the purpose already in force changes nothing.
CREATE OR REPLACE FUNCTION public.set_workspace_purpose(p_company_id uuid, p_purpose text, p_reason text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_latest text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE = '28000'; END IF;
  IF p_company_id IS NULL OR p_purpose IS NULL OR p_purpose NOT IN ('client', 'test', 'training')
     OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 3 AND 500 THEN
    RETURN jsonb_build_object('outcome', 'invalid_request');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.companies c WHERE c.id = p_company_id AND c.user_id = v_uid) THEN
    RETURN jsonb_build_object('outcome', 'forbidden');
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('workspace_purpose:' || p_company_id::text, 0));
  SELECT e.purpose INTO v_latest FROM public.workspace_purpose_events e WHERE e.company_id = p_company_id ORDER BY e.seq DESC LIMIT 1;
  IF v_latest = p_purpose THEN RETURN jsonb_build_object('outcome', 'unchanged', 'purpose', p_purpose); END IF;
  INSERT INTO public.workspace_purpose_events (company_id, purpose, reason, actor_user_id) VALUES (p_company_id, p_purpose, btrim(p_reason), v_uid);
  RETURN jsonb_build_object('outcome', 'recorded', 'purpose', p_purpose);
END;
$$;
